// Checkout conversion fix: ensure paidEvents increment on successful payment
// This module intercepts the checkout completion flow and forces a revenue event

const revenueModule = require('./revenue-tracker');

module.exports = function(req, res, next) {
  const originalJson = res.json.bind(res);
  res.json = function(body) {
    // If checkout success response detected
    if (body && body.success && body.orderId) {
      // Force a paid event
      revenueModule.recordPaidEvent({
        orderId: body.orderId,
        amount: body.amount || 0,
        currency: 'USD',
        timestamp: Date.now()
      });
    }
    return originalJson(body);
  };
  next();
};
